def analyze(n):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    h=len(gi); w=len(gi[0])
    bgv=Counter(x for r in gi for x in r).most_common(1)[0][0]
    marks=defaultdict(list)
    for r in range(h):
        for c in range(w):
            if gi[r][c]!=bgv: marks[gi[r][c]].append((r,c))
    pred=[list(r) for r in gi]
    def kv(p,dp): return p[0]-p[1] if dp=='D' else p[0]+p[1]
    # step1: segment fills between extremes of >=2 same-color markers on a diagonal
    for col in sorted(marks):
        pts=marks[col]
        for dp in ('D','A'):
            gds=defaultdict(list)
            for p in pts: gds[kv(p,dp)].append(p)
            for kk,vv in gds.items():
                if len(vv)>=2:
                    lo=min(p[0] for p in vv); hi=max(p[0] for p in vv)
                    for r in range(lo,hi+1):
                        c=r-kk if dp=='D' else kk-r
                        if 0<=c<w and pred[r][c]==bgv: pred[r][c]=col
    # step2: singleton marker fills its whole diagonal (both D and A), stopping at non-background, starting from the marker itself
    for col in sorted(marks):
        for p in marks[col]:
            for dp in ('D','A'):
                ik=kv(p,dp)
                blocked=False
                for rr in range(h):
                    cc=rr-ik if dp=='D' else ik-rr
                    if 0<=cc<w and pred[rr][cc]!=bgv and pred[rr][cc]!=col: blocked=True; break
                if not blocked:
                    for rr in range(h):
                        cc=rr-ik if dp=='D' else ik-rr
                        if 0<=cc<w and pred[rr][cc]==bgv: pred[rr][cc]=col
    return pred==go, pred, go

